import{_ as e,o as r,c as t,a2 as b}from"./chunks/framework.doxMM-x8.js";const p=JSON.parse('{"title":"模块边界","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/module-boundaries","contentType":"concept","prev":{"text":"项目结构","link":"/architecture/project-structure"},"next":false},"headers":[],"relativePath":"architecture/module-boundaries.md","filePath":"architecture/module-boundaries.md"}'),d={name:"architecture/module-boundaries.md"};function o(s,a,n,l,i,c){return r(),t("div",null,[...a[0]||(a[0]=[b(`<h1 id="模块边界" tabindex="-1">模块边界 <a class="header-anchor" href="#模块边界" aria-label="Permalink to &quot;模块边界&quot;">​</a></h1><p>Lab 拥有实验室业务。Platform Core 拥有身份、成员、凭据、文件、审计、幂等与限流，Core 不导入 Lab。Node 应用通过公开能力组合两者，决定见 <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/adr/0010-single-typescript-lab-word-server.md" target="_blank" rel="noreferrer">ADR 0010</a>与 <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/adr/0011-pglite-embedded-database.md" target="_blank" rel="noreferrer">ADR 0011</a>。</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/web/src/app.ts" target="_blank" rel="noreferrer">应用入口</a>把 Lab 路由、导航与消息交给共享壳。<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/web/src/router.tsx" target="_blank" rel="noreferrer">路由适配</a>拥有 TanStack 类型和浏览器导航；大型页面按需加载。Web 使用生成 SDK/DTO，数据库源码不进入 Web 产物。</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/server/src/runtime.ts" target="_blank" rel="noreferrer">runtime</a>组合服务资源。数据库驱动与迁移执行只属于 platform/db，纯领域不导入基础设施。业务用例拥有事务；Core 审计和幂等与同一业务操作一起提交。</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/server/src/lab/world/schema.ts" target="_blank" rel="noreferrer">Node schema 声明</a>拥有限定表。<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/server/src/lab/ownership.json" target="_blank" rel="noreferrer">Lab ownership</a>记录 Views 路径、准确 SDK helper 路径与合同符号。<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/scripts/check-boundaries.mjs" target="_blank" rel="noreferrer">边界检查</a>检查包依赖、Node 表声明/迁移和 SDK/Core 限制；<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/scripts/lib/server-boundaries.mjs" target="_blank" rel="noreferrer">服务检查</a>追踪 Core/纯领域的间接依赖。静态检查不能证明授权、动态 SQL 或恢复。</p><p>运行总览的<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/views/src/lab/operations-state.ts" target="_blank" rel="noreferrer">汇总与登记区域</a>和<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/views/src/lab/operations-view.tsx" target="_blank" rel="noreferrer">设备视图</a>由 Lab Views 拥有。它们读取现有 World、逐属性观测、趋势和运行记录，不引入第二套身份或服务。共享工作台持有一个世界订阅、布局草稿和设备操作尝试；Core 与通用壳不计算这些业务事实。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>命令从仓库根目录执行。行为通过 HTTP、浏览器和受控资源检查验证，见<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/testing/strategy.md" target="_blank" rel="noreferrer">测试策略</a>与<a href="./lab-word">产品范围</a>。旧静态示例架构保存在历史 ADR 中，不是活动删例或组装框架。</p><hr><p>源码版本：<code>d21b97585cfd</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/architecture/module-boundaries.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,10)])])}const h=e(d,[["render",o]]);export{p as __pageData,h as default};
